/**
 * BU DEMO: Добавить предмет выбранному актёру (через API модуля).
 *
 * ВАЖНО: здесь НЕТ сокетов.
 * Разница с другим демо — берём gateway из game.modules API.
 */
(async () => {
  const token = canvas?.tokens?.controlled?.[0];
  const actor = token?.actor;
  if (!actor) return ui.notifications?.error?.("Выбери токен (актёра), которому добавить предмет.");

  const mod = game.modules?.get?.("blok-upravleniya");
  const GW = mod?.api?.documentGateway;
  if (!GW) return ui.notifications?.error?.("API documentGateway не найден. Убедись что 'Блок управления' активен и socketlib.ready уже прошёл.");

  const itemData = {
    name: `BU Demo Consumable (${game.user?.name ?? "user"})`,
    type: "consumable",
    img: "icons/svg/potion.svg",
    system: {
      quantity: 1
    }
  };

  try {
    const created = await GW.actorCreateEmbedded(actor, "Item", [itemData]);
    const createdName = created?.[0]?.name ?? itemData.name;
    ui.notifications?.info?.(`Добавлено: ${createdName} -> ${actor.name}`);
  } catch (e) {
    console.error(e);
    ui.notifications?.error?.(e?.message ?? String(e));
  }
})();

(async () => {
  /**
   * Макрос для сбора статистики по оружию в игре.
   * Группирует оружие по типам и редкостям, а также собирает данные по крафтам.
   */

  const allWeapons = game.items.filter(item => item.type === "weapon");

  if (allWeapons.length === 0) {
    ui.notifications.warn("В игре не найдено ни одного оружия.");
    return;
  }

  const craftsHandler = window.blokUpravleniyaCrafts || game.blok?.CraftsHandler || null;
  const skillLabels = CONFIG?.DND5E?.skills || {};

  function cloneData(value) {
    if (foundry?.utils?.deepClone) return foundry.utils.deepClone(value);
    if (typeof structuredClone === "function") return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function cleanItemName(name) {
    const normalizedName = String(name || "").trim();
    if (!normalizedName) return "Неизвестно";

    try {
      if (typeof craftsHandler?._removeUniqueCodeFromName === "function") {
        return craftsHandler._removeUniqueCodeFromName(normalizedName);
      }
    } catch (error) {
      console.warn("Не удалось очистить имя предмета от уникального кода:", normalizedName, error);
    }

    return normalizedName;
  }

  function getSkillLabel(skillId, fallbackName) {
    return skillLabels?.[skillId]?.label || fallbackName || skillId || "Неизвестный навык";
  }

  /**
   * Извлекает тип оружия из описания.
   * @param {Item} weapon - Предмет оружия
   * @returns {string}
   */
  function extractWeaponType(weapon) {
    try {
      const description = weapon.system?.description?.value || "";

      const tempDiv = document.createElement("div");
      tempDiv.innerHTML = description;

      const weaponTypeHeader = tempDiv.querySelector("strong");
      if (weaponTypeHeader) {
        const typeText = weaponTypeHeader.textContent;
        const match = typeText.match(/"Оружие"\s+([^<>\n]+)/);
        if (match && match[1]) {
          return match[1].trim();
        }
      }

      const textMatch = description.match(/"Оружие"\s+([^<>\n"']+)/i);
      if (textMatch && textMatch[1]) {
        return textMatch[1].trim();
      }

      return "Неизвестно";
    } catch (error) {
      console.error(`Ошибка при извлечении типа оружия для "${weapon.name}":`, error);
      return "Ошибка";
    }
  }

  /**
   * Извлекает редкость оружия из описания.
   * @param {Item} weapon - Предмет оружия
   * @returns {string}
   */
  function extractWeaponRarity(weapon) {
    try {
      const description = weapon.system?.description?.value || "";

      const tempDiv = document.createElement("div");
      tempDiv.innerHTML = description;

      const rarityParagraphs = Array.from(tempDiv.querySelectorAll("p")).filter(p =>
        /РЕДКОСТЬ\s*:/i.test(p.textContent || "")
      );

      if (rarityParagraphs.length > 0) {
        const rarityText = rarityParagraphs[0].textContent || "";
        const match = rarityText.match(/РЕДКОСТЬ\s*:\s*([^<>\n]+)/i);
        if (match && match[1]) {
          return match[1].trim();
        }
      }

      const textMatch = description.match(/РЕДКОСТЬ\s*:\s*([^<>\n"']+)/i);
      if (textMatch && textMatch[1]) {
        return textMatch[1].trim();
      }

      return "Не указано";
    } catch (error) {
      console.error(`Ошибка при извлечении редкости для "${weapon.name}":`, error);
      return "Ошибка";
    }
  }

  /**
   * Извлекает виды урона из описания оружия.
   * @param {Item} weapon - Предмет оружия
   * @returns {Array<{percent: number, type: string}>}
   */
  function extractDamageTypes(weapon) {
    try {
      const description = weapon.system?.description?.value || "";
      if (!description) return [];

      const tempDiv = document.createElement("div");
      tempDiv.innerHTML = description;

      const damageValueElem = tempDiv.querySelector("#damage-value");
      if (!damageValueElem) return [];

      const parentDiv = damageValueElem.closest("div");
      if (!parentDiv) return [];

      const results = [];
      const paragraphs = parentDiv.querySelectorAll("p");
      for (const p of paragraphs) {
        const text = p.textContent || "";
        const match = text.match(/^\s*-\s*(\d+)%\s+(.+?)\s*$/);
        if (match) {
          results.push({
            percent: parseInt(match[1], 10),
            type: match[2].trim().toLowerCase()
          });
        }
      }

      return results;
    } catch (error) {
      console.error(`Ошибка при извлечении видов урона для "${weapon.name}":`, error);
      return [];
    }
  }

  function getCraftPages(weapon) {
    try {
      if (typeof craftsHandler?._getCraftPagesData === "function") {
        const data = craftsHandler._getCraftPagesData(weapon);
        if (Array.isArray(data?.pages)) return data.pages;
      }
    } catch (error) {
      console.warn(`Не удалось получить страницы крафта через CraftsHandler для "${weapon.name}":`, error);
    }

    const raw = cloneData(weapon.getFlag?.("blok-upravleniya", "craft") || {});
    if (!raw || typeof raw !== "object" || Object.keys(raw).length === 0) return [];
    return Array.isArray(raw.pages) && raw.pages.length > 0 ? raw.pages : [raw];
  }

  function hasAssemblyCraft(page) {
    try {
      if (typeof craftsHandler?._hasRealCraftContent === "function") {
        return !!craftsHandler._hasRealCraftContent(page);
      }
    } catch (error) {
      console.warn("Не удалось проверить содержимое крафта через CraftsHandler:", error);
    }

    const hasSkills = (page?.skills?.sets || []).some(set => (set?.skills?.length || 0) > 0 || (set?.features?.length || 0) > 0);
    const hasTools = (page?.tools?.sets || []).some(set => (set?.items?.length || 0) > 0);
    const hasResources = (page?.resources?.sets || []).some(set => (set?.items?.length || 0) > 0);
    const hasFailureResources = (page?.failureResources?.sets || []).some(set => (set?.items?.length || 0) > 0);
    return hasSkills || hasTools || hasResources || hasFailureResources;
  }

  function hasDisassemblyCraft(page) {
    const disassembly = page?.disassembly || {};
    const hasSkills = (disassembly.skills?.sets || []).some(set => (set?.skills?.length || 0) > 0 || (set?.features?.length || 0) > 0);
    const hasTools = (disassembly.tools?.sets || []).some(set => (set?.items?.length || 0) > 0);
    const hasOutputs = (disassembly.outputs?.sets || []).some(set => (set?.items?.length || 0) > 0);
    const hasFailureOutputs = (disassembly.failureOutputs?.sets || []).some(set => (set?.items?.length || 0) > 0);
    return hasSkills || hasTools || hasOutputs || hasFailureOutputs;
  }

  function getModeLabel(mode) {
    return mode === "ONE_OF" ? "один из" : "все";
  }

  function collectItemSetLines(section) {
    const sets = Array.isArray(section?.sets) ? section.sets : [];
    const lines = [];

    sets.forEach((set, index) => {
      const items = Array.isArray(set?.items) ? set.items : [];
      if (!items.length) return;

      const renderedItems = items.map(item => {
        const qty = Math.max(1, Number(item?.qty) || 1);
        return `${cleanItemName(item?.name || item?.uuid)} (x${qty})`;
      });

      lines.push(`Набор ${index + 1} [${getModeLabel(set?.mode)}]: ${renderedItems.join(", ")}`);
    });

    return lines;
  }

  function collectSkillSetLines(section) {
    const sets = Array.isArray(section?.sets) ? section.sets : [];
    const lines = [];

    sets.forEach((set, index) => {
      const skillEntries = Array.isArray(set?.skills) ? set.skills : [];
      const featureEntries = Array.isArray(set?.features) ? set.features : [];
      const renderedEntries = [];

      for (const skill of skillEntries) {
        const requiredValue = Math.max(1, Number(skill?.value) || 1);
        renderedEntries.push(`${getSkillLabel(skill?.id, skill?.name)} >= ${requiredValue}`);
      }

      for (const feature of featureEntries) {
        renderedEntries.push(`Особенность: ${cleanItemName(feature?.name || feature?.uuid)}`);
      }

      if (!renderedEntries.length) return;
      lines.push(`Набор ${index + 1} [${getModeLabel(set?.mode)}]: ${renderedEntries.join("; ")}`);
    });

    return lines;
  }

  function collectDifficultySetLines(section, fallbackDifficulty = null) {
    const sets = Array.isArray(section?.sets) ? section.sets : [];
    const lines = [];

    sets.forEach((set, index) => {
      const skillEntries = Array.isArray(set?.skills) ? set.skills : [];
      const baseDc = Math.max(1, Number(set?.dc) || 1);
      const avgSuffix = set?.avg ? ", среднее" : "";

      if (set?.mode === "ONE_OF") {
        const renderedEntries = skillEntries.map(skill => {
          const dc = Math.max(1, Number(skill?.dc ?? baseDc) || 1);
          return `${getSkillLabel(skill?.id, skill?.name)}: СЛ ${dc}`;
        });

        if (renderedEntries.length) {
          lines.push(`Набор ${index + 1} [${getModeLabel(set?.mode)}${avgSuffix}]: ${renderedEntries.join("; ")}`);
        } else {
          lines.push(`Набор ${index + 1} [${getModeLabel(set?.mode)}${avgSuffix}]: СЛ ${baseDc}`);
        }
        return;
      }

      const renderedSkills = skillEntries.map(skill => getSkillLabel(skill?.id, skill?.name));
      const skillText = renderedSkills.length ? renderedSkills.join(", ") : "без указания навыка";
      lines.push(`Набор ${index + 1} [${getModeLabel(set?.mode)}]: ${skillText} (СЛ ${baseDc}${avgSuffix})`);
    });

    if (!lines.length) {
      const legacyDifficulty = Math.max(0, Number(fallbackDifficulty) || 0);
      if (legacyDifficulty > 1) {
        lines.push(`СЛ ${legacyDifficulty}`);
      }
    }

    return lines;
  }

  function formatProgress(requiredPoints, attemptsCount) {
    const parts = [];
    const normalizedRequiredPoints = Math.max(0, Number(requiredPoints) || 0);
    const normalizedAttemptsCount = Math.max(0, Number(attemptsCount) || 0);

    if (normalizedRequiredPoints > 0) parts.push(`очки: ${normalizedRequiredPoints}`);
    if (normalizedAttemptsCount > 0) parts.push(`попытки: ${normalizedAttemptsCount}`);

    return parts.length ? parts.join(", ") : "не задан (старая система)";
  }

  function extractCraftSummary(weapon) {
    const pages = getCraftPages(weapon);
    const summarizedPages = [];

    pages.forEach((page, index) => {
      const assemblyPresent = hasAssemblyCraft(page);
      const disassemblyPresent = hasDisassemblyCraft(page);

      if (!assemblyPresent && !disassemblyPresent) return;

      const summaryPage = {
        index: index + 1,
        assembly: null,
        disassembly: null
      };

      if (assemblyPresent) {
        summaryPage.assembly = {
          resultName: weapon.name,
          resultQty: Math.max(1, Number(page?.resultQty) || 1),
          difficultyLines: collectDifficultySetLines(page?.difficultySets, page?.difficulty),
          requirementLines: collectSkillSetLines(page?.skills),
          toolLines: collectItemSetLines(page?.tools),
          resourceLines: collectItemSetLines(page?.resources),
          failureResourceLines: collectItemSetLines(page?.failureResources),
          progressText: formatProgress(page?.requiredPoints, page?.attemptsCount)
        };
      }

      if (disassemblyPresent) {
        const disassembly = page?.disassembly || {};
        summaryPage.disassembly = {
          sourceName: weapon.name,
          disassemblyQty: Math.max(1, Number(disassembly?.disassemblyQty) || 1),
          difficultyLines: collectDifficultySetLines(disassembly?.difficultySets, disassembly?.difficulty ?? page?.difficulty),
          requirementLines: collectSkillSetLines(disassembly?.skills),
          toolLines: collectItemSetLines(disassembly?.tools),
          outputLines: collectItemSetLines(disassembly?.outputs),
          failureOutputLines: collectItemSetLines(disassembly?.failureOutputs),
          progressText: formatProgress(disassembly?.requiredPoints, disassembly?.attemptsCount)
        };
      }

      summarizedPages.push(summaryPage);
    });

    return {
      hasAny: summarizedPages.length > 0,
      hasAssembly: summarizedPages.some(page => !!page.assembly),
      hasDisassembly: summarizedPages.some(page => !!page.disassembly),
      assemblyPageCount: summarizedPages.filter(page => !!page.assembly).length,
      disassemblyPageCount: summarizedPages.filter(page => !!page.disassembly).length,
      pages: summarizedPages
    };
  }

  function formatSectionText(label, lines, indent = "      ", emptyLabel = "не указано", skipIfEmpty = false) {
    if (!Array.isArray(lines) || lines.length === 0) {
      if (skipIfEmpty) return "";
      return `${indent}${label}: ${emptyLabel}\n`;
    }

    if (lines.length === 1) {
      return `${indent}${label}: ${lines[0]}\n`;
    }

    let text = `${indent}${label}:\n`;
    for (const line of lines) {
      text += `${indent}  - ${line}\n`;
    }
    return text;
  }

  function formatCraftEntryAsText(weaponRecord) {
    const craftSummary = weaponRecord.craftSummary;
    let text = `[${weaponRecord.name}] [${weaponRecord.type}] [${weaponRecord.rarity}]\n`;
    text += "-".repeat(50) + "\n";

    for (const page of craftSummary.pages) {
      text += `  Рецепт ${page.index}:\n`;

      if (page.assembly) {
        text += "    Сборка:\n";
        text += `      Результат: ${page.assembly.resultName} x${page.assembly.resultQty}\n`;
        text += formatSectionText("Проверка", page.assembly.difficultyLines);
        text += formatSectionText("Требования", page.assembly.requirementLines);
        text += formatSectionText("Инструменты", page.assembly.toolLines);
        text += formatSectionText("Ресурсы", page.assembly.resourceLines);
        text += formatSectionText("Потери при провале", page.assembly.failureResourceLines, "      ", "нет", true);
        text += `      Прогресс: ${page.assembly.progressText}\n`;
      }

      if (page.disassembly) {
        text += "    Разборка:\n";
        text += `      Расход предмета: ${page.disassembly.sourceName} x${page.disassembly.disassemblyQty}\n`;
        text += formatSectionText("Проверка", page.disassembly.difficultyLines);
        text += formatSectionText("Требования", page.disassembly.requirementLines);
        text += formatSectionText("Инструменты", page.disassembly.toolLines);
        text += formatSectionText("Выходы", page.disassembly.outputLines);
        text += formatSectionText("Потери при провале", page.disassembly.failureOutputLines, "      ", "нет", true);
        text += `      Прогресс: ${page.disassembly.progressText}\n`;
      }

      text += "\n";
    }

    return text;
  }

  const statistics = {};
  const weaponsByType = {};
  const rarityStatistics = {};
  const weaponsByRarity = {};
  const damageTypeStats = {};
  const damageTypeCombos = {};
  const weaponRecords = [];
  const craftStats = {
    anyWeaponCount: 0,
    assemblyWeaponCount: 0,
    disassemblyWeaponCount: 0,
    assemblyPageCount: 0,
    disassemblyPageCount: 0
  };

  for (const weapon of allWeapons) {
    const weaponType = extractWeaponType(weapon);
    const weaponRarity = extractWeaponRarity(weapon);
    const damageTypes = extractDamageTypes(weapon);
    const craftSummary = extractCraftSummary(weapon);

    const damageComboStr = damageTypes.length > 0
      ? damageTypes.map(damageType => `${damageType.percent}% ${damageType.type}`).join(" ")
      : "не указано";

    const weaponRecord = {
      name: weapon.name,
      id: weapon.id,
      type: weaponType,
      rarity: weaponRarity,
      damageTypes,
      damageCombo: damageComboStr,
      craftSummary
    };

    weaponRecords.push(weaponRecord);

    if (!statistics[weaponType]) {
      statistics[weaponType] = 0;
      weaponsByType[weaponType] = [];
    }
    statistics[weaponType]++;
    weaponsByType[weaponType].push(weaponRecord);

    if (!rarityStatistics[weaponRarity]) {
      rarityStatistics[weaponRarity] = 0;
      weaponsByRarity[weaponRarity] = [];
    }
    rarityStatistics[weaponRarity]++;
    weaponsByRarity[weaponRarity].push(weaponRecord);

    for (const damageType of damageTypes) {
      if (!damageTypeStats[damageType.type]) {
        damageTypeStats[damageType.type] = { weaponCount: 0, totalPercent: 0 };
      }
      damageTypeStats[damageType.type].weaponCount++;
      damageTypeStats[damageType.type].totalPercent += damageType.percent;
    }

    if (!damageTypeCombos[damageComboStr]) {
      damageTypeCombos[damageComboStr] = 0;
    }
    damageTypeCombos[damageComboStr]++;

    if (craftSummary.hasAny) craftStats.anyWeaponCount++;
    if (craftSummary.hasAssembly) craftStats.assemblyWeaponCount++;
    if (craftSummary.hasDisassembly) craftStats.disassemblyWeaponCount++;
    craftStats.assemblyPageCount += craftSummary.assemblyPageCount;
    craftStats.disassemblyPageCount += craftSummary.disassemblyPageCount;
  }

  const sortedTypes = Object.entries(statistics)
    .sort((a, b) => b[1] - a[1]);

  const sortedRarities = Object.entries(rarityStatistics)
    .sort((a, b) => b[1] - a[1]);

  const sortedDamageTypes = Object.entries(damageTypeStats)
    .sort((a, b) => b[1].weaponCount - a[1].weaponCount);

  const sortedDamageCombos = Object.entries(damageTypeCombos)
    .filter(([combo]) => combo !== "не указано")
    .sort((a, b) => b[1] - a[1]);

  const sortedWeaponsWithCraft = weaponRecords
    .filter(record => record.craftSummary.hasAny)
    .sort((a, b) => a.name.localeCompare(b.name));

  function formatCraftsAsText() {
    let text = "\nСТАТИСТИКА ПО КРАФТАМ:\n";
    text += "─".repeat(50) + "\n";
    text += `${"Оружий с любым крафтом".padEnd(30)} | ${craftStats.anyWeaponCount}\n`;
    text += `${"Оружий со сборкой".padEnd(30)} | ${craftStats.assemblyWeaponCount}\n`;
    text += `${"Оружий с разборкой".padEnd(30)} | ${craftStats.disassemblyWeaponCount}\n`;
    text += `${"Страниц сборки".padEnd(30)} | ${craftStats.assemblyPageCount}\n`;
    text += `${"Страниц разборки".padEnd(30)} | ${craftStats.disassemblyPageCount}\n`;
    text += `${"Без крафта".padEnd(30)} | ${allWeapons.length - craftStats.anyWeaponCount}\n`;

    text += "\n" + "─".repeat(50) + "\n";
    text += "\nКРАФТЫ ОРУЖИЯ:\n";
    text += "═".repeat(50) + "\n\n";

    if (sortedWeaponsWithCraft.length === 0) {
      text += "Оружие с крафтами не найдено.\n";
      return text;
    }

    for (const weaponRecord of sortedWeaponsWithCraft) {
      text += formatCraftEntryAsText(weaponRecord);
    }

    return text;
  }

  function formatResultsAsText() {
    let text = "=== СТАТИСТИКА ОРУЖИЯ ===\n\n";
    text += `Всего найдено оружий: ${allWeapons.length}\n\n`;

    text += "СТАТИСТИКА ПО ТИПАМ:\n";
    text += "─".repeat(50) + "\n";
    for (const [weaponType, count] of sortedTypes) {
      text += `${weaponType.padEnd(30)} | ${count}\n`;
    }

    text += "\n" + "─".repeat(50) + "\n";
    text += "\nСТАТИСТИКА ПО РЕДКОСТЯМ:\n";
    text += "─".repeat(50) + "\n";
    for (const [rarity, count] of sortedRarities) {
      text += `${rarity.padEnd(30)} | ${count}\n`;
    }

    text += "\n" + "─".repeat(50) + "\n";
    text += "\nСТАТИСТИКА ПО ВИДАМ УРОНА:\n";
    text += "─".repeat(50) + "\n";
    text += `${"Вид урона".padEnd(25)} | ${"Оружий".padStart(7)} | ${"Средний %".padStart(9)}\n`;
    text += "─".repeat(50) + "\n";
    for (const [typeName, stats] of sortedDamageTypes) {
      const avgPct = Math.round(stats.totalPercent / stats.weaponCount);
      text += `${typeName.padEnd(25)} | ${String(stats.weaponCount).padStart(7)} | ${String(`${avgPct}%`).padStart(9)}\n`;
    }

    if (sortedDamageCombos.length > 0) {
      text += "\n" + "─".repeat(50) + "\n";
      text += "\nТОП КОМБИНАЦИИ УРОНА:\n";
      text += "─".repeat(50) + "\n";
      for (const [combo, count] of sortedDamageCombos) {
        text += `${combo.padEnd(40)} | ${count}\n`;
      }
    }

    text += "\n" + "─".repeat(50) + "\n";
    text += "\nДЕТАЛЬНЫЙ СПИСОК ОРУЖИЙ ПО ТИПАМ:\n";
    text += "═".repeat(50) + "\n\n";

    for (const [weaponType, weapons] of Object.entries(weaponsByType)) {
      text += `[${weaponType}] (${weapons.length} шт.)\n`;
      text += "-".repeat(50) + "\n";
      for (const weaponRecord of weapons.sort((a, b) => a.name.localeCompare(b.name))) {
        text += `  • ${weaponRecord.name} [${weaponRecord.rarity}] [${weaponRecord.damageCombo}]\n`;
      }
      text += "\n";
    }

    text += "\nДЕТАЛЬНЫЙ СПИСОК ОРУЖИЙ ПО РЕДКОСТЯМ:\n";
    text += "═".repeat(50) + "\n\n";

    for (const [rarity, weapons] of Object.entries(weaponsByRarity)) {
      text += `[${rarity}] (${weapons.length} шт.)\n`;
      text += "-".repeat(50) + "\n";
      for (const weaponRecord of weapons.sort((a, b) => a.name.localeCompare(b.name))) {
        text += `  • ${weaponRecord.name} [${weaponRecord.type}] [${weaponRecord.damageCombo}]\n`;
      }
      text += "\n";
    }

    return text;
  }

  const craftsText = formatCraftsAsText();
  const resultsText = `${formatResultsAsText()}${craftsText}`;

  let htmlContent = `
    <div style="background:#1b1b1b;color:#ddd;padding:16px;border:1px solid #333;border-radius:6px;font-family:Arial,sans-serif;">
      <div style="font-size:20px;font-weight:700;color:#ffd700;margin-bottom:16px;text-align:center;">
