   * @param {Item} weapon - Предмет оружия
   * @returns {string} Тип оружия или "Неизвестно"
   */
  function extractWeaponType(weapon) {
    try {
      const description = weapon.system?.description?.value || "";

      // Создаем временный DOM элемент для парсинга HTML
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      // Ищем заголовок с типом оружия (паттерн: "Оружие" Тип)
      const weaponTypeHeader = tempDiv.querySelector('strong');
      if (weaponTypeHeader) {
        const typeText = weaponTypeHeader.textContent;
        const match = typeText.match(/"Оружие"\s+([^<>\n]+)/);
        if (match && match[1]) {
          return match[1].trim();
        }
      }

      // Альтернативный способ: поиск в тексте описания
      const textMatch = description.match(/"Оружие"\s+([^<>\n"']+)/i);
      if (textMatch && textMatch[1]) {
        return textMatch[1].trim();
      }

      return "Неизвестно";
    } catch (error) {
      console.error(`Ошибка при извлечении типа оружия для "${weapon.name}":`, error);
      return "Ошибка";
    }
  }

