(async () => {
  const ABILITY_NAME = "Шизофрения";
  const warn = m => ui.notifications?.warn?.(m);
  const err = m => ui.notifications?.error?.(m);
  const info = m => ui.notifications?.info?.(m);

  // Получаем конфигурацию из NonstandardSkillsHandler
  const handler = game.modules?.get('blok-upravleniya')?.api?.nonstandardSkillsHandler;
  const cfg = handler?.schizophrenia || {
    abilityName: "Шизофрения",
    minSpawnFeet: 15,
    maxSpawnFeet: 30,
    triggerChance: 0.10,
    compendiumCollection: "world.shizofreniya",
    compendiumFolderId: "KXd2nwqvv2VQ6z0D",
    actorFolderName: "Шизофрения"
  };

  const logs = [];
  const addLog = (type, message, data = null) => {
    logs.push({ type, message, data, time: new Date().toLocaleTimeString() });
  };

  // Функция для получения актера с способностью
  async function findActorWithAbility() {
    addLog("info", "=== Поиск актера с способностью ===");

    const selectedToken = canvas.tokens.controlled?.[0];
    if (selectedToken?.actor) {
      addLog("info", `Выбран токен: ${selectedToken.name}`, { tokenId: selectedToken.id, actorId: selectedToken.actor.id });
      const hasAbility = !!selectedToken.actor.items.find(i => i.type === "feat" && String(i.name || '').trim() === cfg.abilityName);
      if (hasAbility) {
        addLog("success", `✓ У выбранного актера найдена способность "${cfg.abilityName}"`);
        return { token: selectedToken, actor: selectedToken.actor };
      } else {
        addLog("warning", `✗ У выбранного актера НЕ найдена способность "${cfg.abilityName}"`);
        addLog("info", "Ищем способность среди всех актеров на сцене...");
      }
    } else {
      addLog("info", "Токен не выбран, ищем среди всех актеров на сцене...");
    }

    const scene = game.scenes?.active;
    if (!scene) {
      addLog("error", "✗ Нет активной сцены!");
      return null;
    }
    addLog("success", `✓ Активная сцена найдена: ${scene.name}`, { sceneId: scene.id });

    const found = [];
    for (const tokenDoc of scene.tokens) {
      const actor = tokenDoc.actor;
      if (!actor) continue;

      const hasAbility = !!actor.items.find(i => i.type === "feat" && String(i.name || '').trim() === cfg.abilityName);
      if (hasAbility) {
        const token = tokenDoc.object || canvas.tokens.get(tokenDoc.id);
        found.push({ token, actor });
        addLog("success", `✓ Найден актер с способностью: ${actor.name}`, { 
          actorId: actor.id, 
          tokenId: tokenDoc.id,
          tokenName: token?.name || tokenDoc.name
        });
      }
    }

    if (found.length === 0) {
      addLog("error", `✗ Не найдено ни одного актера с способностью "${cfg.abilityName}" на активной сцене`);
      return null;
    }

    if (found.length > 1) {
      addLog("warning", `Найдено ${found.length} актеров с способностью. Используем первого.`);
    }

    return found[0];
  }

  // Проверка прав доступа
  function checkProcessingRights(actor) {
    addLog("info", "=== Проверка прав обработки ===");

    const isGM = game.user.isGM;
    addLog("info", `Текущий пользователь: ${game.user.name}`, { isGM });

    const gmOnline = game.users.some(u => u.isGM && u.active);
    addLog("info", `ГМ онлайн: ${gmOnline ? "Да" : "Нет"}`);

    const isOwner = !!actor?.isOwner;
    addLog("info", `Владелец актера: ${isOwner ? "Да" : "Нет"}`);

    let shouldProcess = false;
    if (isGM) {
      shouldProcess = true;
      addLog("success", "✓ ГМ может обрабатывать");
    } else {
      if (gmOnline) {
        addLog("warning", "✗ ГМ онлайн, обычный пользователь не может обрабатывать");
      } else {
        if (isOwner) {
          shouldProcess = true;
          addLog("success", "✓ Владелец актера может обрабатывать (ГМ нет)");
        } else {
          addLog("error", "✗ Не владелец актера и ГМ нет");
        }
      }
    }

    return shouldProcess;
  }

  // Проверка компендиума
  async function checkCompendium() {
    addLog("info", "=== Проверка компендиума ===");

    const collectionId = cfg.compendiumCollection;
    addLog("info", `ID компендиума: ${collectionId}`);

    const pack = game.packs?.get(collectionId);
    if (!pack) {
      addLog("error", `✗ Компендиум "${collectionId}" не найден!`);
      addLog("info", "Доступные компендиумы:", Object.keys(game.packs || {}));
      return null;
    }
    addLog("success", `✓ Компендиум найден: ${pack.metadata?.label || pack.title || collectionId}`);

    const folderId = cfg.compendiumFolderId;
    addLog("info", `ID папки в компендиуме: ${folderId}`);

    try {
      let docs = await pack.getDocuments();
      addLog("info", `Всего документов в компендиуме: ${docs.length}`);

      docs = (docs || []).filter(d => d?.documentName === 'Actor' || d instanceof Actor || d?.constructor?.name === 'Actor');
      addLog("info", `Актеров в компендиуме: ${docs.length}`);

      if (folderId) {
        const normalizeId = (doc) => doc.folder?.id || (doc.folder?.uuid ? doc.folder.uuid.split('.').pop() : undefined);
        const filtered = docs.filter(d => normalizeId(d) === folderId);
        addLog("info", `Актеров в папке "${folderId}": ${filtered.length}`);

        if (filtered.length > 0) {
          addLog("success", `✓ Найдено ${filtered.length} актеров в указанной папке`);
          return { pack, docs: filtered, folderId };
        } else {
          addLog("warning", `⚠ В указанной папке нет актеров, используем все актеры из компендиума`);
          return { pack, docs, folderId: null };
        }
      } else {
        addLog("warning", "⚠ ID папки не указан, используем все актеры из компендиума");
        return { pack, docs, folderId: null };
      }
    } catch (e) {
      addLog("error", `✗ Ошибка при загрузке документов из компендиума: ${e.message}`, e);
      return null;
    }
  }

  // Проверка папки в мире
  function checkWorldFolder() {
    addLog("info", "=== Проверка папки в мире ===");

    const folderName = cfg.actorFolderName;
    addLog("info", `Имя папки: "${folderName}"`);

    const folder = game.folders?.find?.(f => f.type === 'Actor' && f.name === folderName);
    if (folder) {
      addLog("success", `✓ Папка найдена: ${folder.name}`, { folderId: folder.id });
      return folder;
    } else {
      addLog("warning", `⚠ Папка "${folderName}" не найдена, будет создана при импорте`);
      return null;
    }
  }

  // Проверка мирового времени
  function checkWorldTime() {
    addLog("info", "=== Проверка мирового времени ===");

    const worldTimeSeconds = Number(game.time?.worldTime || 0) || 0;
    addLog("info", `Мировое время (секунды): ${worldTimeSeconds}`);

    // Используем ту же логику, что и в _getGameTime
    const startDate = new Date(1492, 0, 1, 0, 0, 0);
    const gameDate = new Date(startDate.getTime() + (worldTimeSeconds * 1000));

    const time = {
      hour: gameDate.getHours(),
      minute: gameDate.getMinutes(),
      second: gameDate.getSeconds(),
      year: gameDate.getFullYear(),
      month: gameDate.getMonth() + 1,
      day: gameDate.getDate(),
      weekDay: gameDate.getDay()
    };

    addLog("info", `Игровое время: ${time.day}.${time.month}.${time.year} ${time.hour}:${String(time.minute).padStart(2, '0')}:${String(time.second).padStart(2, '0')}`);
    addLog("info", `Текущий час: ${time.hour}`);

    // Проверяем последний обработанный час (если доступен)
    if (handler?._schizoLastHour !== undefined && handler._schizoLastHour !== null) {
      addLog("info", `Последний обработанный час: ${handler._schizoLastHour}`);
      const passed = (time.hour - handler._schizoLastHour) % 24;
      addLog("info", `Прошло часов: ${passed}`);
    } else {
      addLog("warning", "⚠ Последний обработанный час не установлен (первый запуск)");
    }

    return time;
  }

  // Проверка шанса срабатывания
  function checkTriggerChance() {
    addLog("info", "=== Проверка шанса срабатывания ===");

    const chance = cfg.triggerChance;
    const chancePercent = chance * 100;
    addLog("info", `Шанс срабатывания: ${chancePercent}% (${chance})`);

    const testRoll = Math.random();
    const wouldTrigger = testRoll < chance;
    addLog("info", `Тестовый бросок: ${(testRoll * 100).toFixed(2)}%`, { 
      wouldTrigger: wouldTrigger ? "✓ Сработало бы" : "✗ Не сработало бы" 
    });

    return { chance, chancePercent, wouldTrigger };
  }

  // Попытка триггера способности
  async function attemptTrigger(actorData, compendiumData) {
    addLog("info", "=== Попытка триггера способности ===");

    if (!actorData) {
      addLog("error", "✗ Нет данных актера для триггера");
      return false;
    }

    if (!compendiumData || !compendiumData.docs || compendiumData.docs.length === 0) {
      addLog("error", "✗ Нет актеров в компендиуме для спавна");
      return false;
    }

    const { token, actor } = actorData;
    const { docs } = compendiumData;

    try {
      // Выбираем случайного актера
      const sourceActorDoc = docs[Math.floor(Math.random() * docs.length)];
      addLog("info", `Выбран актер из компендиума: ${sourceActorDoc.name}`, { actorId: sourceActorDoc.id });

      // Импортируем в мир
      addLog("info", "Импортируем актера в мир...");
      const data = sourceActorDoc.toObject();
      delete data._id;
      data.flags = data.flags || {};
      data.flags.core = data.flags.core || {};
      data.flags.core.sourceId = sourceActorDoc.uuid;

      const folder = checkWorldFolder();
      if (folder) {
        data.folder = folder.id;
        addLog("info", `Устанавливаем папку: ${folder.name}`);
      }

      const createdActor = await Actor.create(data);
      addLog("success", `✓ Актер создан в мире: ${createdActor.name}`, { actorId: createdActor.id });

      // Создаем токен
      addLog("info", "Создаем токен рядом с владельцем...");
      addLog("info", `Позиция владельца: x=${token.x}, y=${token.y}`);
      addLog("info", `Дистанция спавна: ${cfg.minSpawnFeet}-${cfg.maxSpawnFeet} футов`);

      // Используем метод из handler, если доступен
      if (handler?._spawnLinkedActorTokenNear) {
        await handler._spawnLinkedActorTokenNear(
          token,
          createdActor,
          cfg.minSpawnFeet,
          cfg.maxSpawnFeet
        );
        addLog("success", "✓ Токен создан");
        return true;
      } else {
        addLog("error", "✗ Метод _spawnLinkedActorTokenNear не доступен в handler");
        return false;
      }
    } catch (e) {
      addLog("error", `✗ Ошибка при триггере: ${e.message}`, e);
      return false;
    }
  }

  // Основная функция диагностики
  async function runDiagnostics() {
    logs.length = 0; // Очищаем логи

    addLog("info", "=== ДИАГНОСТИКА СПОСОБНОСТИ 'ШИЗОФРЕНИЯ' ===");
    addLog("info", `Время запуска: ${new Date().toLocaleString()}`);
    addLog("info", "");

    // 1. Поиск актера
    const actorData = await findActorWithAbility();
    if (!actorData) {
      showLogsDialog();
      return;
    }

    // 2. Проверка прав
    const canProcess = checkProcessingRights(actorData.actor);
    if (!canProcess) {
      addLog("warning", "⚠ Недостаточно прав для обработки, но продолжаем диагностику...");
    }

    // 3. Проверка компендиума
    const compendiumData = await checkCompendium();
    if (!compendiumData) {
      showLogsDialog();
      return;
    }

    // 4. Проверка папки в мире
    checkWorldFolder();

    // 5. Проверка времени
    checkWorldTime();

    // 6. Проверка шанса
    checkTriggerChance();

    // Показываем результаты
    showLogsDialog(actorData, compendiumData, canProcess);
  }

  // Показ диалога с логами
  function showLogsDialog(actorData = null, compendiumData = null, canProcess = false) {
    const logHtml = logs.map(log => {
      const color = log.type === "error" ? "#ff6b6b" : 
                    log.type === "warning" ? "#ffa500" : 
                    log.type === "success" ? "#51cf66" : 
                    "#adb5bd";
      const icon = log.type === "error" ? "✗" : 
                   log.type === "warning" ? "⚠" : 
                   log.type === "success" ? "✓" : 
                   "•";

      let dataHtml = "";
      if (log.data) {
        try {
          dataHtml = `<div style="margin-left: 20px; font-size: 11px; color: #868e96; font-family: monospace;">${JSON.stringify(log.data, null, 2)}</div>`;
        } catch (e) {
          dataHtml = `<div style="margin-left: 20px; font-size: 11px; color: #868e96;">[Данные не сериализуются]</div>`;
        }
      }

      return `
        <div style="margin-bottom: 8px; padding: 4px 0; border-bottom: 1px solid #2d3436;">
          <span style="color: ${color}; font-weight: bold;">${icon}</span>
          <span style="color: ${color};">${log.message}</span>
          <span style="color: #868e96; font-size: 10px; margin-left: 8px;">[${log.time}]</span>
          ${dataHtml}
        </div>
      `;
    }).join("");

    const canTrigger = actorData && compendiumData && canProcess && compendiumData.docs.length > 0;

