(async () => {
  const OLD_ASSET_ROOT_RE = /systems\/dnd5e\/icons\//gi;
  const NEW_ASSET_ROOT = "systems/fallout-maw/icons/";

  const INCLUDE_WORLD_ITEMS = true;
  const INCLUDE_ACTOR_ITEMS = true;
  const INCLUDE_ITEM_PACKS = true;
  const PACK_NAME_FILTER = null;
  const DRY_RUN = false;

  const normalizeAssetPath = (value) => {
    if (typeof value !== "string") return value;
    return value.replace(OLD_ASSET_ROOT_RE, NEW_ASSET_ROOT);
  };

  const collectWeaponUpdate = (item) => {
    const source = item?.toObject?.();
    if (!source) return null;

    const flat = foundry.utils.flattenObject(source);
    const updates = {};
    const touched = [];

    for (const [key, value] of Object.entries(flat)) {
      if (typeof value !== "string") continue;
      if (!OLD_ASSET_ROOT_RE.test(value)) continue;

      OLD_ASSET_ROOT_RE.lastIndex = 0;
      const nextValue = normalizeAssetPath(value);
      if (nextValue === value) continue;

      updates[key] = nextValue;
      touched.push(key);
    }

    if (!touched.length) return null;
    return { updates, touched };
  };

  const updateWeapon = async (item, sourceLabel, stats) => {
    const patch = collectWeaponUpdate(item);
    if (!patch) {
      stats.skipped += 1;
      return;
    }

    stats.checked += 1;
    stats.changed += 1;
    stats.examples.push(`${sourceLabel}: ${item.name}`);

    if (DRY_RUN) return;
    await item.update(patch.updates);
  };

  const shouldProcessPack = (pack) => {
    if (!pack) return false;
    if (pack.documentName !== "Item") return false;
    if (pack.locked) return false;
    if (PACK_NAME_FILTER && !PACK_NAME_FILTER.test(pack.collection)) return false;
    return true;
  };

  const stats = {
    checked: 0,
    changed: 0,
    skipped: 0,
    errors: []
  };
  stats.examples = [];

  try {
    if (INCLUDE_WORLD_ITEMS) {
      for (const item of game.items.filter((entry) => entry.type === "weapon")) {
        try {
          await updateWeapon(item, "Мир", stats);
        } catch (error) {
          stats.errors.push(`Мир :: ${item.name} :: ${error.message}`);
        }
      }
    }

    if (INCLUDE_ACTOR_ITEMS) {
      for (const actor of game.actors) {
        for (const item of actor.items.filter((entry) => entry.type === "weapon")) {
          try {
            await updateWeapon(item, `Актёр ${actor.name}`, stats);
          } catch (error) {
            stats.errors.push(`Актёр ${actor.name} :: ${item.name} :: ${error.message}`);
          }
        }
      }
    }

    if (INCLUDE_ITEM_PACKS) {
      for (const pack of game.packs.filter(shouldProcessPack)) {
        let documents = [];
        try {
          documents = await pack.getDocuments();
        } catch (error) {
          stats.errors.push(`Пак ${pack.collection} :: загрузка :: ${error.message}`);
          continue;
        }

        for (const item of documents.filter((entry) => entry.type === "weapon")) {
          try {
            await updateWeapon(item, `Пак ${pack.collection}`, stats);
          } catch (error) {
            stats.errors.push(`Пак ${pack.collection} :: ${item.name} :: ${error.message}`);
          }
        }
      }
    }

    const exampleLines = stats.examples.slice(0, 10);
    const summary = [
      `Проверено оружий с заменами: ${stats.changed}`,
      `Без старых путей: ${stats.skipped}`,
      `Ошибок: ${stats.errors.length}`,
      DRY_RUN ? "Режим: dry-run, изменения не записывались." : "Изменения записаны."
    ];

    if (exampleLines.length) {
      summary.push("");
      summary.push("Примеры:");
      summary.push(...exampleLines.map((line) => `- ${line}`));
    }

    if (stats.errors.length) {
      summary.push("");
      summary.push("Ошибки:");
      summary.push(...stats.errors.slice(0, 10).map((line) => `- ${line}`));
    }

    console.log("[fix-legacy-weapon-sound-paths-macro] Итог:", {
      changed: stats.changed,
      skipped: stats.skipped,
      errors: stats.errors
    });

    ui.notifications.info(
      DRY_RUN
        ? `Проверка завершена: найдено ${stats.changed} оружий со старыми путями.`
        : `Готово: обновлено ${stats.changed} оружий со старыми путями.`
    );

    ChatMessage.create({
      content: `<pre>${summary.join("\n")}</pre>`
    });
  } catch (error) {
    console.error("[fix-legacy-weapon-sound-paths-macro] Ошибка:", error);
    ui.notifications.error(`Макрос завершился с ошибкой: ${error.message}`);
  }
})();

/**
 * Макрос для размещения уникальных токенов из папки
 * Позволяет выбрать папку, проверяет какие токены уже есть на сцене,
 * и размещает по клику мыши только те токены, которых еще нет
 */

class UniqueTokenPlacer {
    constructor() {
        this.availableActors = [];
        this.currentIndex = 0;
        this.isPlacing = false;
        this.clickHandler = null;
    }

    /**
     * Получить все папки с акторами
     */
    _getFoldersWithActors() {
        const folders = [];

        // Получаем все папки акторов
        game.folders.forEach(folder => {
            if (folder.type === "Actor" && folder.contents.length > 0) {
                folders.push({
                    id: folder.id,
                    name: folder.name,
                    count: folder.contents.length
                });
            }
        });

        // Сортируем по имени
        return folders.sort((a, b) => a.name.localeCompare(b.name));
    }

    /**
     * Создать dropdown для выбора папки
     */
    _createFolderDropdown(folders, containerId) {
        const container = document.getElementById(containerId);
        if (!container) return;

        // Очищаем контейнер
        container.innerHTML = '';

        // Создаем wrapper для dropdown
        const wrapper = document.createElement('div');
        wrapper.style.cssText = 'position: relative; width: 100%;';

        // Создаем input для поиска
        const searchInput = document.createElement('input');
        searchInput.type = 'text';
        searchInput.placeholder = 'Найти папку...';
        searchInput.style.cssText = `
            width: 100%; 
            padding: 8px; 
            border: 1px solid #ccc; 
            border-radius: 4px;
            box-sizing: border-box;
        `;

        // Создаем список опций
        const optionsList = document.createElement('div');
        optionsList.style.cssText = `
            position: absolute;
            top: 100%;
            left: 0;
            right: 0;
            background: white;
            border: 1px solid #ccc;
            border-top: none;
            max-height: 200px;
            overflow-y: auto;
            z-index: 1000;
            display: none;
        `;

        let selectedFolderId = null;

        // Функция для отображения опций
        const showOptions = (searchTerm = '') => {
            optionsList.innerHTML = '';

            const filteredFolders = folders.filter(folder => 
                folder.name.toLowerCase().includes(searchTerm.toLowerCase())
            );

            if (filteredFolders.length === 0) {
                const noResults = document.createElement('div');
                noResults.textContent = 'Папки не найдены';
                noResults.style.cssText = 'padding: 8px; color: #666; font-style: italic;';
                optionsList.appendChild(noResults);
            } else {
                filteredFolders.forEach(folder => {
                    const option = document.createElement('div');
                    option.textContent = `${folder.name} (${folder.count} акторов)`;
                    option.style.cssText = `
                        padding: 8px;
                        cursor: pointer;
                        border-bottom: 1px solid #eee;
                    `;
                    option.setAttribute('data-folder-id', folder.id);

                    option.addEventListener('mouseenter', () => {
                        option.style.backgroundColor = '#f0f0f0';
                    });

                    option.addEventListener('mouseleave', () => {
                        option.style.backgroundColor = '';
                    });

                    option.addEventListener('click', () => {
                        selectedFolderId = folder.id;
                        searchInput.value = folder.name;
                        optionsList.style.display = 'none';
                        container.setAttribute('data-selected-folder', folder.id);
                    });

                    optionsList.appendChild(option);
                });
            }

            optionsList.style.display = 'block';
        };

        // Обработчики событий для поиска
        searchInput.addEventListener('input', (e) => {
            showOptions(e.target.value);
        });

        searchInput.addEventListener('focus', () => {
            showOptions(searchInput.value);
        });

        // Скрытие списка при клике вне его
        document.addEventListener('click', (e) => {
            if (!wrapper.contains(e.target)) {
                optionsList.style.display = 'none';
            }
        });

        wrapper.appendChild(searchInput);
        wrapper.appendChild(optionsList);
        container.appendChild(wrapper);

        return {
            getSelectedFolderId: () => selectedFolderId,
            clear: () => {
                searchInput.value = '';
                selectedFolderId = null;
                optionsList.style.display = 'none';
                container.removeAttribute('data-selected-folder');
            }
        };
    }

    /**
     * Показать диалог выбора папки
     */
    async showFolderSelectionDialog() {
        const folders = this._getFoldersWithActors();

        if (folders.length === 0) {
            ui.notifications.warn("Не найдено папок с акторами!");
            return null;
        }

        return new Promise((resolve) => {
            const dialog = new Dialog({
                title: "Выбор папки для размещения токенов",
                content: `
                    <style>
                        .token-placer-dialog {
                            padding: 10px;
                        }
                        .token-placer-info {
                            background: #f0f8ff;
                            border: 1px solid #b0d4f1;
                            border-radius: 4px;
                            padding: 10px;
                            margin-bottom: 15px;
                            font-size: 14px;
                        }
                        .token-placer-folder-section {
                            margin-bottom: 15px;
                        }
                        .token-placer-folder-section label {
                            display: block;
                            margin-bottom: 5px;
                            font-weight: bold;
                        }
                    </style>
                    <div class="token-placer-dialog">
                        <div class="token-placer-info">
                            <strong>Инструкция:</strong><br>
                            1. Выберите папку с акторами<br>
                            2. Нажмите "Начать размещение"<br>
                            3. Кликайте левой кнопкой мыши на сцене для размещения токенов<br>
                            4. Будут размещены только те токены, которых еще нет на сцене<br>
                            5. Нажмите ESC для отмены размещения
                        </div>

                        <div class="token-placer-folder-section">
                            <label>Выберите папку с акторами:</label>
                            <div id="folder-selector-container"></div>
                        </div>
                    </div>
                `,
                buttons: {
                    start: {
                        icon: '<i class="fas fa-play"></i>',
                        label: "Начать размещение",
                        callback: (html) => {
                            const selectedFolderId = html.find('#folder-selector-container').attr('data-selected-folder');
                            if (!selectedFolderId) {
                                ui.notifications.warn("Выберите папку!");
                                return false;
                            }
                            resolve(selectedFolderId);
                        }
                    },
                    cancel: {
                        icon: '<i class="fas fa-times"></i>',
                        label: "Отмена",
                        callback: () => resolve(null)
                    }
                },
                default: "start",
                render: (html) => {
                    // Инициализируем dropdown после рендера
                    setTimeout(() => {
                        this._createFolderDropdown(folders, 'folder-selector-container');
                    }, 100);
                },
                close: () => resolve(null)
            });

            dialog.render(true);
        });
    }

    /**
     * Получить токены, которых еще нет на сцене
     */
    getAvailableActors(folderId) {
        const folder = game.folders.get(folderId);
        if (!folder) {
            ui.notifications.error("Папка не найдена!");
            return [];
        }

        // Получаем всех акторов из папки
        const folderActors = folder.contents;

        // Получаем ID всех токенов на текущей сцене
        const existingTokenActorIds = new Set();
        canvas.tokens.placeables.forEach(token => {
            if (token.actor) {
                existingTokenActorIds.add(token.actor.id);
            }
        });

        // Фильтруем акторов, которых еще нет на сцене
        const availableActors = folderActors.filter(actor => 
            !existingTokenActorIds.has(actor.id)
        );

        return availableActors;
    }

    /**
     * Начать размещение токенов
     */
    async startPlacement(folderId) {
        this.availableActors = this.getAvailableActors(folderId);

        if (this.availableActors.length === 0) {
            ui.notifications.info("Все токены из выбранной папки уже размещены на сцене!");
            return;
        }

        this.currentIndex = 0;
        this.isPlacing = true;

        ui.notifications.info(`Начинаю размещение. Доступно ${this.availableActors.length} уникальных токенов. Кликайте по сцене для размещения. ESC для отмены.`);

        // Создаем обработчик кликов
        this.clickHandler = this.onCanvasClick.bind(this);
        canvas.stage.on('click', this.clickHandler);

        // Создаем обработчик ESC
        this.escHandler = this.onEscapeKey.bind(this);
        document.addEventListener('keydown', this.escHandler);

        // Показываем подсказку
        this.showPlacementHint();
    }

    /**
     * Показать подсказку о текущем размещении
     */
    showPlacementHint() {
        if (!this.isPlacing || this.currentIndex >= this.availableActors.length) return;

        const currentActor = this.availableActors[this.currentIndex];
        const remaining = this.availableActors.length - this.currentIndex;

        ui.notifications.info(`Следующий токен: ${currentActor.name} (осталось: ${remaining})`);
    }

    /**
     * Обработчик клика по canvas
     */
    async onCanvasClick(event) {
        if (!this.isPlacing || this.currentIndex >= this.availableActors.length) {
            this.stopPlacement();
            return;
        }

        // Получаем позицию клика
        const position = event.data.getLocalPosition(canvas.tokens);

        // Привязываем к сетке
        const snappedX = Math.round(position.x / canvas.grid.size) * canvas.grid.size;
        const snappedY = Math.round(position.y / canvas.grid.size) * canvas.grid.size;

        try {
            // Размещаем токен
            const actor = this.availableActors[this.currentIndex];

            // Получаем данные токена из прототипа актора
            const prototypeToken = actor.prototypeToken;

            const tokenData = {
                name: actor.name,
                x: snappedX,
                y: snappedY,
                actorId: actor.id,
                texture: {
                    src: prototypeToken.texture.src || actor.img
                },
                width: prototypeToken.width || 1,
                height: prototypeToken.height || 1,
                scale: prototypeToken.texture.scaleX || 1,
                hidden: false,
                disposition: prototypeToken.disposition || 0,
                displayName: prototypeToken.displayName || 0,
                displayBars: prototypeToken.displayBars || 0,
                bar1: prototypeToken.bar1 || {},
                bar2: prototypeToken.bar2 || {}
            };

            await canvas.scene.createEmbeddedDocuments('Token', [tokenData]);

            ui.notifications.info(`Размещен токен: ${actor.name}`);

            this.currentIndex++;

            // Проверяем, есть ли еще токены
            if (this.currentIndex >= this.availableActors.length) {
                ui.notifications.info("Все доступные токены размещены!");
                this.stopPlacement();
            } else {
                this.showPlacementHint();
            }

        } catch (error) {
            console.error("Ошибка при размещении токена:", error);
            ui.notifications.error(`Ошибка при размещении токена: ${error.message}`);
        }
    }

    /**
     * Обработчик нажатия ESC
     */
    onEscapeKey(event) {
        if (event.key === 'Escape' && this.isPlacing) {
            this.stopPlacement();
            ui.notifications.info("Размещение токенов отменено.");
        }
    }

    /**
     * Остановить размещение токенов
     */
    stopPlacement() {
        this.isPlacing = false;

        if (this.clickHandler) {
            canvas.stage.off('click', this.clickHandler);
            this.clickHandler = null;
        }

        if (this.escHandler) {
            document.removeEventListener('keydown', this.escHandler);
            this.escHandler = null;
        }

        this.availableActors = [];
        this.currentIndex = 0;
    }

    /**
     * Основная функция запуска макроса
     */
    async run() {
        // Проверяем, что мы на сцене
        if (!canvas.scene) {
            ui.notifications.warn("Откройте сцену для размещения токенов!");
            return;
        }

        // Останавливаем предыдущее размещение, если оно было активно
        if (this.isPlacing) {
            this.stopPlacement();
        }

        // Показываем диалог выбора папки
        const selectedFolderId = await this.showFolderSelectionDialog();

        if (selectedFolderId) {
            await this.startPlacement(selectedFolderId);
        }
    }
}

