(async () => {
  /**
   * Показывает все пистолеты, где найден режим очереди,
   * и выводит соответствующие строки из описания.
   */

  function extractWeaponType(weapon) {
    try {
      const description = weapon.system?.description?.value || "";
      if (!description) return null;
      const temp = document.createElement("div");
      temp.innerHTML = description;
      const strong = temp.querySelector("strong");
      const text = strong?.textContent || "";
      const match = text.match(/"Оружие"\s+([^<>\n]+)/i);
      return match?.[1]?.trim() || null;
    } catch {
      return null;
    }
  }

  function extractBurstModeLines(weapon) {
    const description = weapon.system?.description?.value || "";
    if (!description) return [];

    const temp = document.createElement("div");
    temp.innerHTML = description;
    const lines = [];

    // 1) Явные action-id из шаблона
    const modeNodes = temp.querySelectorAll(".weapon-mode[data-action-id]");
    for (const node of modeNodes) {
      const actionId = (node.getAttribute("data-action-id") || "").toLowerCase();
      const text = (node.textContent || "").replace(/\s+/g, " ").trim();
      if (!text) continue;

      if (actionId === "burst-shot" || /очеред/i.test(text)) {
        lines.push(`action-id=${actionId || "?"}: ${text}`);
      }
    }

    // 2) Фолбэк: любые строки с "Очередь" в тексте описания
    const plainText = (temp.textContent || "").split("\n").map(s => s.trim()).filter(Boolean);
    for (const row of plainText) {
      if (/очеред/i.test(row) && !lines.some(x => x.includes(row))) {
        lines.push(`text: ${row}`);
      }
    }

    return Array.from(new Set(lines));
  }

  const pistols = game.items.filter(i => i.type === "weapon" && extractWeaponType(i) === "Пистолет");
  if (pistols.length === 0) {
    ui.notifications.warn("Пистолеты не найдены.");
    return;
  }

  const found = [];
  for (const pistol of pistols) {
    const burstLines = extractBurstModeLines(pistol);
    if (burstLines.length > 0) {
      found.push({
        name: pistol.name,
        lines: burstLines
      });
    }
  }

  let report = "=== ПИСТОЛЕТЫ С РЕЖИМОМ ОЧЕРЕДИ ===\n\n";
  report += `Всего пистолетов проверено: ${pistols.length}\n`;
  report += `Найдено с режимом очереди: ${found.length}\n\n`;

  if (found.length === 0) {
    report += "Совпадений не найдено.\n";
  } else {
    for (const item of found.sort((a, b) => a.name.localeCompare(b.name, "ru"))) {
      report += `${item.name}\n`;
      for (const line of item.lines) {
        report += `  - ${line}\n`;
      }
      report += "\n";
    }
  }

  const html = `
    <div style="background:#1b1b1b;color:#ddd;padding:16px;border:1px solid #333;border-radius:6px;font-family:Arial,sans-serif;">
      <div style="font-size:18px;font-weight:700;color:#ffd700;margin-bottom:12px;text-align:center;">
        Пистолеты с режимом очереди
      </div>
      <div style="margin-bottom:8px;">Проверено пистолетов: <b>${pistols.length}</b></div>
      <div style="margin-bottom:12px;">Найдено: <b>${found.length}</b></div>
      <textarea id="burst-report" readonly style="width:100%;height:280px;background:#242424;color:#ddd;border:1px solid #444;border-radius:4px;padding:8px;font-family:monospace;font-size:12px;resize:vertical;"></textarea>
      <button id="copy-burst-report" style="margin-top:8px;width:100%;background:#4a5568;color:#fff;border:1px solid #555;border-radius:4px;padding:8px;cursor:pointer;font-weight:600;">
        Копировать отчет
      </button>
    </div>
  `;

  new Dialog({
    title: "Режим очереди у пистолетов",
    content: html,
    buttons: {
      close: { label: "Закрыть" }
    },
    default: "close",
    render: dlg => {
      const wc = dlg[0]?.closest(".window-content");
      if (wc) wc.style.background = "#1b1b1b";

      const ta = dlg.find("#burst-report");
      ta.val(report);

      dlg.find("#copy-burst-report").on("click", async () => {
        try {
          ta[0].select();
          const ok = document.execCommand("copy");
          if (!ok) await navigator.clipboard.writeText(report);
          ui.notifications.info("Отчет скопирован.");
        } catch {
          ui.notifications.warn("Не удалось скопировать автоматически.");
        }
      });
    }
  }, { width: 860 }).render(true);

  console.log(report);
})();

(async () => {
  /**
   * Макрос для создания подпапок с названиями навыков в указанной папке
   */

  const folderId = "6Q385hGlin7l68Xg";

  // Проверяем существование папки
  const parentFolder = game.folders.get(folderId);
  if (!parentFolder) {
    ui.notifications.error(`Папка с ID ${folderId} не найдена!`);
    return;
  }

  // Получаем все навыки из системы dnd5e, исключая "Очки действия" (act)
  const skills = CONFIG.DND5E?.skills || {};
  const skillKeys = Object.keys(skills).filter(key => key !== "act");

  if (skillKeys.length === 0) {
    ui.notifications.error("Не удалось найти навыки в системе dnd5e!");
    return;
  }

  try {
    ui.notifications.info(`Создание подпапок для ${skillKeys.length} навыков...`);

    let createdCount = 0;
    let existingCount = 0;

    // Обрабатываем каждый навык отдельно
    for (const skillKey of skillKeys) {
      const skillConfig = skills[skillKey];
      // Получаем локализованное название навыка
      const skillLabel = game.i18n.localize(skillConfig.label) || skillKey;

      // Проверяем, существует ли уже подпапка с таким названием
      const existingFolder = parentFolder.children.find(f => 
        f.name === skillLabel && f.type === parentFolder.type
      );

      if (existingFolder) {
        existingCount++;
        console.log(`Подпапка "${skillLabel}" уже существует, пропускаем`);
        continue;
      }

      // Создаем подпапку для навыка
      try {
        const skillFolder = await Folder.create({
          name: skillLabel,
          type: parentFolder.type,
          parent: folderId
        });
        createdCount++;
        console.log(`Создана подпапка: ${skillLabel}`);
      } catch (error) {
        console.error(`Ошибка при создании подпапки "${skillLabel}":`, error);
        ui.notifications.warn(`Не удалось создать подпапку "${skillLabel}": ${error.message}`);
      }
    }

    ui.notifications.info(
      `Готово! Создано подпапок: ${createdCount}, уже существовало: ${existingCount}`
    );
  } catch (error) {
    console.error("Ошибка при создании подпапок навыков:", error);
    ui.notifications.error(`Ошибка при создании подпапок: ${error.message}`);
  }
})();

