    }

    const description = item.system?.description?.value || "";
    return /"Снаряжение"/i.test(description);
  }

  /**
   * Извлекает редкость снаряжения из описания
   */
  function extractRarity(equipment) {
    try {
      const description = equipment.system?.description?.value || "";

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      const rarityParagraphs = Array.from(tempDiv.querySelectorAll('p')).filter(p => 
        /РЕДКОСТЬ\s*:/i.test(p.textContent || '')
      );

      if (rarityParagraphs.length > 0) {
        const rarityText = rarityParagraphs[0].textContent || '';
        const match = rarityText.match(/РЕДКОСТЬ\s*:\s*([^<>\n]+)/i);
        if (match && match[1]) {
          return match[1].trim();
        }
      }

      const textMatch = description.match(/РЕДКОСТЬ\s*:\s*([^<>\n"']+)/i);
      if (textMatch && textMatch[1]) {
        return textMatch[1].trim();
      }

      return null;
    } catch (error) {
      console.error(`Ошибка при извлечении редкости для "${equipment.name}":`, error);
      return null;
    }
  }

  /**
   * Нормализует редкость (приводит к правильному формату)
   */
  function normalizeRarity(rarity) {
    if (!rarity || typeof rarity !== 'string') {
      return null;
    }

    const trimmed = rarity.trim();
    if (!trimmed) {
      return null;
    }

    const lowerRarity = trimmed.toLowerCase().trim();

    const baseForms = {
      'обычн': 'Обычный',
      'необычн': 'Необычный',
      'редк': 'Редкий',
      'эпическ': 'Эпический',
      'легендарн': 'Легендарный',
      'уникальн': 'Уникальный',
      'дикая пустош': 'Дикая Пустошь',
      'дикая пустын': 'Дикая Пустошь',
      'дикая': 'Дикая Пустошь'
    };

    for (const correct of CORRECT_RARITIES) {
      if (correct.toLowerCase() === lowerRarity) {
        return correct;
      }
    }

    for (const [base, correct] of Object.entries(baseForms)) {
      if (lowerRarity.startsWith(base)) {
        return correct;
      }
    }

    const normalizedLower = lowerRarity.replace(/[оеаяий]$/, '');
    for (const [base, correct] of Object.entries(baseForms)) {
      if (normalizedLower === base || normalizedLower.startsWith(base) || base.startsWith(normalizedLower)) {
        return correct;
      }
    }

    return null;
  }

  /**
   * Извлекает занимаемые слоты из описания снаряжения
   */
  function extractSlots(equipment) {
    try {
      const description = equipment.system?.description?.value || "";
      if (!description) {
        return [];
      }

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      const sections = Array.from(tempDiv.querySelectorAll('.terminal-section')).filter(sec => 
        /ЗАНИМАЕТ/i.test(sec.textContent || '')
      );

      if (sections.length === 0) {
        return [];
      }

      const section = sections[0];
      const slotElements = section.querySelectorAll('.armor-slot');
      const slots = Array.from(slotElements).map(el => {
        const text = el.textContent || '';
        return text.trim();
      }).filter(slot => slot.length > 0);

      return slots;
    } catch (error) {
      console.error(`Ошибка при извлечении слотов для "${equipment.name}":`, error);
      return [];
    }
  }

  /**
   * Вычисляет защиту для каждой части тела на основе слотов и редкости
   */
  function calculateProtection(rarity, slots) {
    const rarityIndex = RARITY_INDEX[rarity];
    if (rarityIndex === undefined) {
      return {};
    }

    const protection = {};
    for (const bodyPart of BODY_PARTS) {
      protection[bodyPart] = 0;
    }

    for (const slot of slots) {
      const normalizedSlot = slot.trim();

      if (SLOT_PROTECTION[normalizedSlot]) {
        const slotProt = SLOT_PROTECTION[normalizedSlot];
        for (const [bodyPart, values] of Object.entries(slotProt)) {
          if (values && values[rarityIndex] !== undefined) {
            protection[bodyPart] = (protection[bodyPart] || 0) + values[rarityIndex];
          }
        }
        continue;
      }

      const slotLower = normalizedSlot.toLowerCase();
      for (const [slotName, slotProt] of Object.entries(SLOT_PROTECTION)) {
        const slotNameLower = slotName.toLowerCase();
        if (slotLower === slotNameLower || 
            slotNameLower.startsWith(slotLower) || 
            slotLower.startsWith(slotNameLower)) {
          for (const [bodyPart, values] of Object.entries(slotProt)) {
            if (values && values[rarityIndex] !== undefined) {
              protection[bodyPart] = (protection[bodyPart] || 0) + values[rarityIndex];
            }
          }
          break;
        }
      }
    }

    return protection;
  }

  /**
   * Вычисляет максимальное состояние на основе слотов и редкости
   */
  function calculateMaxDurability(rarity, slots) {
    const rarityIndex = RARITY_INDEX[rarity];
    if (rarityIndex === undefined) {
      return null;
    }

    let totalDurability = 0;
    let hasValidSlots = false;

    for (const slot of slots) {
      const normalizedSlot = slot.trim();

      if (SLOT_DURABILITY[normalizedSlot] && SLOT_DURABILITY[normalizedSlot][rarityIndex] !== undefined) {
        totalDurability += SLOT_DURABILITY[normalizedSlot][rarityIndex];
        hasValidSlots = true;
        continue;
      }

      const slotLower = normalizedSlot.toLowerCase();
      for (const [slotName, values] of Object.entries(SLOT_DURABILITY)) {
        const slotNameLower = slotName.toLowerCase();
        if (slotLower === slotNameLower || 
            slotNameLower.startsWith(slotLower) || 
            slotLower.startsWith(slotNameLower)) {
          if (values && values[rarityIndex] !== undefined) {
            totalDurability += values[rarityIndex];
            hasValidSlots = true;
          }
          break;
        }
      }
    }

    return hasValidSlots ? totalDurability : null;
  }

  /**
   * Вычисляет цену на основе редкости и слотов
   */
  function calculatePrice(rarity, slots) {
    if (!rarity || !slots || slots.length === 0) {
      return null;
    }

    let totalPrice = 0;
    let hasValidSlots = false;

    for (const slot of slots) {
      const normalizedSlot = slot.trim();

      if (SLOT_PRICES[normalizedSlot] && SLOT_PRICES[normalizedSlot][rarity]) {
        totalPrice += SLOT_PRICES[normalizedSlot][rarity];
        hasValidSlots = true;
        continue;
      }

      const slotLower = normalizedSlot.toLowerCase();
      for (const [slotName, prices] of Object.entries(SLOT_PRICES)) {
        const slotNameLower = slotName.toLowerCase();
        if (slotLower === slotNameLower) {
          if (prices[rarity]) {
            totalPrice += prices[rarity];
            hasValidSlots = true;
          }
          break;
        }
        if (slotNameLower.startsWith(slotLower) || slotLower.startsWith(slotNameLower)) {
          if (prices[rarity]) {
            totalPrice += prices[rarity];
            hasValidSlots = true;
          }
          break;
        }
      }
    }

    return hasValidSlots ? totalPrice : null;
  }

  /**
   * Находит таблицу защиты в описании
   */
  function findProtectionTable(description) {
    try {
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      const sections = Array.from(tempDiv.querySelectorAll('.terminal-section')).filter(sec => 
        /ЗАЩИТА/i.test(sec.textContent || '')
      );

      if (sections.length === 0) {
        return null;
      }

      const section = sections[0];
      const table = section.querySelector('table');
      return table || null;
    } catch (error) {
      console.error("Ошибка при поиске таблицы защиты:", error);
      return null;
    }
  }

  /**
   * Обновляет значения защиты в таблице
   */
  async function updateProtection(equipment, protection, rarity) {
    try {
      const description = equipment.system?.description?.value || "";
      if (!description) {
        return false;
      }

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      const sections = Array.from(tempDiv.querySelectorAll('.terminal-section')).filter(sec => 
        /ЗАЩИТА/i.test(sec.textContent || '')
      );

      if (sections.length === 0) {
        return false;
      }

      const section = sections[0];
      const table = section.querySelector('table');
      if (!table) {
        return false;
      }

      const rows = Array.from(table.querySelectorAll('tbody tr'));
      if (rows.length === 0) {
        rows.push(...Array.from(table.querySelectorAll('tr')));
      }

      let updated = false;
      let cellsUpdated = 0;

      for (const row of rows) {
        if (row.querySelector('th')) {
          continue;
        }

        const firstCell = row.querySelector('td');
        if (!firstCell) continue;

        const damageTypeText = (firstCell.textContent || '').trim();
        const isZeroProtection = ZERO_PROTECTION_TYPES.some(type => 
          damageTypeText.toLowerCase().includes(type.toLowerCase())
        );

        const dataCells = Array.from(row.querySelectorAll('td')).slice(1);

        for (let i = 0; i < dataCells.length && i < BODY_PARTS.length; i++) {
          const bodyPart = BODY_PARTS[i];
          const cell = dataCells[i];

          if (!cell) continue;

          let protectionValue = 0;
          if (!isZeroProtection && protection[bodyPart] !== undefined) {
            protectionValue = protection[bodyPart];
          }

          const formattedValue = protectionValue > 0 ? `+${protectionValue}%` : `${protectionValue}%`;

          const strongEl = cell.querySelector('strong');
          if (strongEl) {
            const oldValue = strongEl.textContent.trim();
            strongEl.textContent = formattedValue;
            if (oldValue !== formattedValue) {
              updated = true;
              cellsUpdated++;
            }
          } else {
            cell.innerHTML = `<p><span style="font-family: 'Courier New', Courier, monospace"><strong style="color:#FFD700">${formattedValue}</strong></span></p>`;
            updated = true;
            cellsUpdated++;
          }
        }
      }

      if (updated) {
        console.log(`Обновлено ${cellsUpdated} ячеек защиты для "${equipment.name}"`);
      }

      const newDescription = tempDiv.innerHTML;

      if (newDescription !== description) {
        await equipment.update({ 'system.description.value': newDescription });
        await new Promise(resolve => setTimeout(resolve, 50));
        return true;
      } else {
        return true;
      }
    } catch (error) {
      console.error(`Ошибка при обновлении защиты для "${equipment.name}":`, error);
      return false;
    }
  }

  /**
   * Извлекает текущие значения состояния из описания
   */
  function extractDurabilityValues(equipment) {
    try {
      const description = equipment.system?.description?.value || "";
      if (!description) {
        return { current: null, max: null };
      }

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      const durCurrentElem = tempDiv.querySelector('#durability-value');
      const durMaxElem = tempDiv.querySelector('#durability-max');

      const current = durCurrentElem ? parseInt(durCurrentElem.textContent) : null;
      const max = durMaxElem ? parseInt(durMaxElem.textContent) : null;

      return {
        current: isNaN(current) ? null : current,
        max: isNaN(max) ? null : max
      };
    } catch (error) {
      console.error(`Ошибка при извлечении состояния для "${equipment.name}":`, error);
      return { current: null, max: null };
    }
  }

  /**
   * Обновляет значения состояния в описании снаряжения
   */
  async function updateDurabilityValues(equipment, newMax, newCurrent) {
    try {
      const description = equipment.system?.description?.value || "";
      if (!description) {
        return false;
      }

      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = description;

      let updated = false;

      const durMaxElem = tempDiv.querySelector('#durability-max');
      if (durMaxElem) {
        durMaxElem.textContent = newMax;
        updated = true;
      }

      const durCurrentElem = tempDiv.querySelector('#durability-value');
      if (durCurrentElem) {
        durCurrentElem.textContent = newCurrent !== null ? newCurrent : newMax;
        updated = true;
      }

      if (updated) {
        const newDescription = tempDiv.innerHTML;
        await equipment.update({ 'system.description.value': newDescription });
        return true;
      }

      return false;
    } catch (error) {
      console.error(`Ошибка при обновлении состояния для "${equipment.name}":`, error);
      return false;
    }
  }

  /**
   * Извлекает текущую цену и валюту снаряжения
   */
  function extractPrice(equipment) {
    try {
      const price = equipment.system?.price;
      if (!price) {
        return { price: null, currency: null };
      }

      if (typeof price === 'object' && price !== null) {
        return {
          price: price.value || null,
          currency: price.denomination || null
        };
      }

      if (typeof price === 'number') {
        return {
          price: price,
          currency: null
        };
      }

      return { price: null, currency: null };
    } catch (error) {
      console.error(`Ошибка при извлечении цены для "${equipment.name}":`, error);
      return { price: null, currency: null };
    }
  }

  /**
   * Обновляет цену и валюту снаряжения
   */
  async function updatePrice(equipment, newPrice, newCurrency) {
    try {
      const updateData = {};

      const currentPrice = equipment.system?.price;

      if (typeof currentPrice === 'object' && currentPrice !== null) {
        updateData['system.price.value'] = newPrice;
        updateData['system.price.denomination'] = newCurrency;
      } else {
        updateData['system.price'] = {
          value: newPrice,
          denomination: newCurrency
        };
      }

      await equipment.update(updateData);
      return true;
    } catch (error) {
      console.error(`Ошибка при обновлении цены для "${equipment.name}":`, error);
      return false;
    }
  }

  // Получаем ID предмета из аргументов макроса или запрашиваем через диалог
  let itemId = null;

  // Проверяем аргументы макроса (если макрос вызван с аргументом)
  if (args && args.length > 0 && args[0]) {
    itemId = args[0].trim();
  } else if (typeof args === 'string') {
    itemId = args.trim();
  }

  // Если ID не передан, запрашиваем через диалог
  if (!itemId) {
    itemId = await new Promise((resolve) => {
      new Dialog({
        title: "Стандартизация снаряжения",
        content: `
          <div style="padding: 10px;">
            <p style="margin-bottom: 10px;">Введите ID предмета для стандартизации:</p>
            <input type="text" id="item-id-input" placeholder="Item.pYd7kEUfnnCQAkTZ" style="width: 100%; padding: 5px;" />
          </div>
        `,
        buttons: {
          ok: {
            label: "Обработать",
            callback: (html) => {
              const input = html.find('#item-id-input')[0];
              resolve(input ? input.value.trim() : null);
            }
          },
          cancel: {
            label: "Отмена",
            callback: () => resolve(null)
          }
        },
        default: "ok"
      }).render(true);
    });
  }

  if (!itemId) {
    ui.notifications.warn("Операция отменена.");
    return;
  }

  // Находим предмет по ID или UUID
  let item = null;

  // Пробуем получить как UUID (если начинается с "Item." или содержит точку)
  if (itemId.startsWith("Item.") || itemId.includes(".")) {
    try {
      item = await fromUuid(itemId);
    } catch (error) {
      console.warn(`Не удалось получить предмет по UUID "${itemId}":`, error);
    }
  }

  // Если не получилось по UUID, пробуем получить как обычный ID
  if (!item) {
    item = game.items.get(itemId);
  }

  // Если все еще не найден, пробуем найти в коллекции по имени или ID
  if (!item) {
    item = game.items.find(i => i.id === itemId || i.name === itemId);
  }

  if (!item) {
    ui.notifications.error(`Предмет с ID "${itemId}" не найден. Попробуйте использовать полный UUID (например, Item.xxx) или ID предмета.`);
    return;
  }

  // Проверяем, является ли предмет снаряжением
  if (!isEquipment(item)) {
    ui.notifications.error(`Предмет "${item.name}" не является снаряжением.`);
    return;
  }

  // Собираем информацию о предмете
  const rarityRaw = extractRarity(item);
  const rarity = normalizeRarity(rarityRaw);
  const slots = extractSlots(item);

  const results = {
    protection: { success: false, error: null },
    durability: { success: false, error: null },
    price: { success: false, error: null }
  };

  // Проверяем базовые данные
  if (!rarity) {
    ui.notifications.error(`Не удалось определить редкость для "${item.name}".`);
    return;
  }

  if (slots.length === 0) {
    ui.notifications.error(`Не удалось определить слоты для "${item.name}".`);
    return;
  }

  // 1. Стандартизация защиты
  try {
    const description = item.system?.description?.value || "";
    const table = findProtectionTable(description);

    if (table) {
      const protection = calculateProtection(rarity, slots);
      if (Object.keys(protection).length > 0) {
        results.protection.success = await updateProtection(item, protection, rarity);
        if (!results.protection.success) {
          results.protection.error = "Не удалось обновить защиту";
        }
      } else {
        results.protection.error = "Не удалось вычислить защиту";
      }
    } else {
      results.protection.error = "Таблица защиты не найдена";
    }
  } catch (error) {
    results.protection.error = error.message || "Неизвестная ошибка";
  }

  // 2. Стандартизация прочности
  try {
    const newMax = calculateMaxDurability(rarity, slots);
    if (newMax) {
      const newCurrent = newMax;
      results.durability.success = await updateDurabilityValues(item, newMax, newCurrent);
      if (!results.durability.success) {
        results.durability.error = "Не удалось обновить прочность";
      }
    } else {
      results.durability.error = "Не удалось вычислить прочность";
    }
  } catch (error) {
    results.durability.error = error.message || "Неизвестная ошибка";
  }

  // 3. Стандартизация цены
  try {
    const newPrice = calculatePrice(rarity, slots);
    if (newPrice) {
      results.price.success = await updatePrice(item, newPrice, STANDARD_CURRENCY);
      if (!results.price.success) {
        results.price.error = "Не удалось обновить цену";
      }
    } else {
      results.price.error = "Не удалось вычислить цену";
    }
  } catch (error) {
    results.price.error = error.message || "Неизвестная ошибка";
  }

  // Получаем текущие значения для отчета
  const currentDurability = extractDurabilityValues(item);
  const currentPrice = extractPrice(item);
  const protection = calculateProtection(rarity, slots);

  // Формируем отчет
  let reportText = `=== ОТЧЕТ О СТАНДАРТИЗАЦИИ СНАРЯЖЕНИЯ ===\n\n`;
  reportText += `Предмет: ${item.name}\n`;
  reportText += `ID: ${itemId}\n`;
  reportText += `Редкость: ${rarity}\n`;
  reportText += `Слоты: ${slots.join(", ")}\n\n`;

  reportText += `РЕЗУЛЬТАТЫ:\n`;
  reportText += `─`.repeat(80) + `\n`;
  reportText += `Защита: ${results.protection.success ? "✓ Обновлено" : `✗ ${results.protection.error || "Ошибка"}`}\n`;
  reportText += `Прочность: ${results.durability.success ? "✓ Обновлено" : `✗ ${results.durability.error || "Ошибка"}`}\n`;
  reportText += `Цена: ${results.price.success ? "✓ Обновлено" : `✗ ${results.price.error || "Ошибка"}`}\n\n`;

  if (results.protection.success) {
    reportText += `ЗАЩИТА:\n`;
    for (const [bodyPart, value] of Object.entries(protection)) {
      if (value > 0) {
        reportText += `  ${bodyPart}: +${value}%\n`;
      }
    }
    reportText += `\n`;
  }

  if (results.durability.success) {
    reportText += `ПРОЧНОСТЬ:\n`;
    reportText += `  Макс.: ${currentDurability.max || "?"}\n`;
    reportText += `  Текущая: ${currentDurability.current || "?"}\n\n`;
  }

  if (results.price.success) {
    reportText += `ЦЕНА:\n`;
    reportText += `  ${currentPrice.price || "?"} ${currentPrice.currency || STANDARD_CURRENCY}\n\n`;
  }

  // Формируем HTML отчет
  let htmlContent = `
    <div style="background:#1b1b1b;color:#ddd;padding:16px;border:1px solid #333;border-radius:6px;font-family:Arial,sans-serif;">
      <div style="font-size:20px;font-weight:700;color:#ffd700;margin-bottom:16px;text-align:center;">
        Стандартизация снаряжения
      </div>

      <div style="margin-bottom:16px;padding:12px;background:#242424;border-radius:4px;">
        <div style="color:#fff;font-weight:600;margin-bottom:8px;font-size:16px;">${item.name}</div>
        <div style="color:#888;font-size:12px;margin-bottom:4px;">ID: <span style="color:#fff;">${itemId}</span></div>
        <div style="color:#888;font-size:12px;margin-bottom:4px;">Редкость: <span style="color:#ffd700;">${rarity}</span></div>
        <div style="color:#888;font-size:12px;">Слоты: <span style="color:#ffd700;">${slots.join(", ")}</span></div>
      </div>

      <div style="margin-bottom:16px;">
        <div style="font-size:16px;font-weight:600;color:#ffd700;margin-bottom:12px;">
          Результаты обработки
        </div>
        <div style="display:grid;grid-template-columns:1fr;gap:8px;">
          <div style="padding:8px;background:#242424;border-radius:4px;border-left:4px solid ${results.protection.success ? '#4ade80' : '#f87171'};">
            <div style="color:#fff;font-weight:600;margin-bottom:4px;">
              ${results.protection.success ? '✓' : '✗'} Защита
            </div>
            <div style="color:#888;font-size:12px;">
              ${results.protection.success ? 'Успешно обновлено' : (results.protection.error || 'Ошибка')}
            </div>
          </div>

          <div style="padding:8px;background:#242424;border-radius:4px;border-left:4px solid ${results.durability.success ? '#4ade80' : '#f87171'};">
            <div style="color:#fff;font-weight:600;margin-bottom:4px;">
              ${results.durability.success ? '✓' : '✗'} Прочность
            </div>
            <div style="color:#888;font-size:12px;">
              ${results.durability.success ? 'Успешно обновлено' : (results.durability.error || 'Ошибка')}
            </div>
          </div>

          <div style="padding:8px;background:#242424;border-radius:4px;border-left:4px solid ${results.price.success ? '#4ade80' : '#f87171'};">
            <div style="color:#fff;font-weight:600;margin-bottom:4px;">
              ${results.price.success ? '✓' : '✗'} Цена
            </div>
            <div style="color:#888;font-size:12px;">
              ${results.price.success ? 'Успешно обновлено' : (results.price.error || 'Ошибка')}
            </div>
          </div>
        </div>
      </div>
  `;

  if (results.protection.success && Object.keys(protection).length > 0) {
    htmlContent += `
      <div style="margin-bottom:16px;">
        <div style="font-size:14px;font-weight:600;color:#ffd700;margin-bottom:8px;">Защита:</div>
        <div style="background:#242424;border-radius:4px;padding:8px;">
    `;
    for (const [bodyPart, value] of Object.entries(protection)) {
      if (value > 0) {
        htmlContent += `
          <div style="color:#888;font-size:12px;margin-bottom:4px;">
            ${bodyPart}: <span style="color:#4ade80;">+${value}%</span>
          </div>
        `;
      }
    }
    htmlContent += `
        </div>
      </div>
    `;
  }

  if (results.durability.success) {
    htmlContent += `
      <div style="margin-bottom:16px;">
        <div style="font-size:14px;font-weight:600;color:#ffd700;margin-bottom:8px;">Прочность:</div>
        <div style="background:#242424;border-radius:4px;padding:8px;">
          <div style="color:#888;font-size:12px;">Макс.: <span style="color:#fff;">${currentDurability.max || "?"}</span></div>
          <div style="color:#888;font-size:12px;">Текущая: <span style="color:#fff;">${currentDurability.current || "?"}</span></div>
        </div>
      </div>
    `;
  }

  if (results.price.success) {
    htmlContent += `
      <div style="margin-bottom:16px;">
        <div style="font-size:14px;font-weight:600;color:#ffd700;margin-bottom:8px;">Цена:</div>
        <div style="background:#242424;border-radius:4px;padding:8px;">
          <div style="color:#888;font-size:12px;">
            <span style="color:#fff;">${currentPrice.price || "?"}</span> 
            <span style="color:#888;">${currentPrice.currency || STANDARD_CURRENCY}</span>
          </div>
        </div>
      </div>
    `;
  }

  htmlContent += `
      <div style="margin-top:16px;padding-top:16px;border-top:1px solid #333;">
        <div style="margin-bottom:8px;color:#ffd700;font-weight:600;font-size:14px;">
          Отчет для копирования:
        </div>
        <textarea id="equipment-report-textarea" readonly 
          style="width:100%;height:200px;background:#242424;color:#ddd;border:1px solid #444;border-radius:4px;padding:8px;font-family:monospace;font-size:12px;resize:vertical;"
        ></textarea>
        <div style="margin-top:8px;display:flex;gap:8px;">
          <button id="copy-report-btn" style="flex:1;background:#4a5568;color:#fff;border:1px solid #555;border-radius:4px;padding:8px;cursor:pointer;font-weight:600;">
            📋 Копировать отчет
          </button>
        </div>
        <div id="copy-status" style="margin-top:8px;color:#4ade80;font-size:12px;display:none;">
          ✓ Отчет скопирован в буфер обмена!
        </div>
      </div>
    </div>
  `;

  // Показываем диалог с результатами
  new Dialog({
    title: "Стандартизация снаряжения",
    content: htmlContent,
    buttons: {
      close: {
        label: "Закрыть",
        callback: () => {}
      }
    },
    default: "close",
    render: html => {
      const wc = html[0]?.closest(".window-content");
      if (wc) wc.style.background = "#1b1b1b";

      const copyBtn = html.find('#copy-report-btn');
      const textarea = html.find('#equipment-report-textarea');
      const statusDiv = html.find('#copy-status');

      textarea.val(reportText);

      copyBtn.on('click', async () => {
        try {
          textarea[0].select();
          textarea[0].setSelectionRange(0, 99999);

          const successful = document.execCommand('copy');

          if (successful) {
            statusDiv.show();
            setTimeout(() => {
              statusDiv.fadeOut(300);
            }, 2000);
            ui.notifications.info("Отчет скопирован в буфер обмена!");
          } else {
            try {
              await navigator.clipboard.writeText(reportText);
              statusDiv.show();
              setTimeout(() => {
                statusDiv.fadeOut(300);
              }, 2000);
              ui.notifications.info("Отчет скопирован в буфер обмена!");
            } catch (err) {
              ui.notifications.warn("Не удалось скопировать автоматически. Выделите текст вручную и скопируйте (Ctrl+C).");
            }
          }
        } catch (error) {
          console.error("Ошибка при копировании:", error);
          ui.notifications.warn("Не удалось скопировать автоматически. Выделите текст вручную и скопируйте (Ctrl+C).");
        }
      });

      textarea.on('dblclick', function() {
        this.select();
      });
    }
  }, { width: 600 }).render(true);

  // Выводим в консоль
  console.log("=== Стандартизация снаряжения ===");
  console.log(`Предмет: ${item.name}`);
  console.log(`ID: ${itemId}`);
  console.log(`Редкость: ${rarity}`);
  console.log(`Слоты: ${slots.join(", ")}`);
  console.log(`Защита: ${results.protection.success ? "✓" : "✗"}`);
