/**
 * Макрос для диагностики лагов при изменении максимального HP
 * Включает отслеживание всех хуков updateActor и собирает статистику
 * 
 * Использование:
 * 1. Запустите макрос один раз для включения мониторинга
 * 2. Измените максимальное HP у персонажа
 * 3. Запустите макрос снова для вывода статистики
 * 4. Скопируйте вывод из консоли и отправьте разработчику
 */

const DEBUG_KEY = 'blokUpravleniyaHPLagDebug';

if (!game[DEBUG_KEY]) {
  // Включаем мониторинг
  game[DEBUG_KEY] = {
    enabled: true,
    hooks: [],
    callStats: {},
    timings: [],
    startTime: Date.now()
  };

  const debug = game[DEBUG_KEY];

  // Очищаем старые данные
  debug.hooks = [];
  debug.callStats = {};
  debug.timings = [];
  debug.startTime = Date.now();

  console.log('%c[HP Lag Debug] Мониторинг ВКЛЮЧЕН', 'color: green; font-weight: bold;');
  console.log('[HP Lag Debug] Измените максимальное HP у персонажа, затем запустите макрос снова для вывода статистики');

  // Перехватываем все хуки updateActor
  const originalCallAll = Hooks.callAll;
  Hooks.callAll = function(hookName, ...args) {
    if (hookName === 'updateActor' && debug.enabled) {
      const hookStart = performance.now();
      const actor = args[0];
      const updateData = args[1];

      // Собираем информацию о вызове
      const callInfo = {
        timestamp: Date.now() - debug.startTime,
        actorId: actor?.id,
        actorName: actor?.name,
        updateDataKeys: updateData ? Object.keys(updateData).join(', ') : 'none',
        hpChanged: updateData?.system?.attributes?.hp !== undefined,
        hpMaxChanged: updateData?.system?.attributes?.hp?.max !== undefined,
        stackTrace: new Error().stack.split('\n').slice(2, 8).join('\n')
      };

      // Вызываем оригинальный метод
      const result = originalCallAll.apply(this, arguments);

      const hookTime = performance.now() - hookStart;
      callInfo.executionTime = hookTime;

      debug.hooks.push(callInfo);
      debug.timings.push(hookTime);

      // Статистика по модулям (пытаемся определить по stack trace)
      const stackLines = callInfo.stackTrace.split('\n');
      let moduleName = 'unknown';
      for (const line of stackLines) {
        if (line.includes('modules/')) {
          const match = line.match(/modules\/([^/]+)/);
          if (match) {
            moduleName = match[1];
            break;
          }
        }
      }

      if (!debug.callStats[moduleName]) {
        debug.callStats[moduleName] = { count: 0, totalTime: 0, maxTime: 0 };
      }
      debug.callStats[moduleName].count++;
      debug.callStats[moduleName].totalTime += hookTime;
      debug.callStats[moduleName].maxTime = Math.max(debug.callStats[moduleName].maxTime, hookTime);

      return result;
    }
    return originalCallAll.apply(this, arguments);
  };

  // Также отслеживаем preUpdateActor
  const originalCall = Hooks.call;
  Hooks.call = function(hookName, ...args) {
    if ((hookName === 'preUpdateActor' || hookName === 'updateActor') && debug.enabled) {
      const hookStart = performance.now();
      const result = originalCall.apply(this, arguments);
      const hookTime = performance.now() - hookStart;

      if (hookTime > 1) { // Логируем только медленные вызовы
        console.warn(`[HP Lag Debug] Медленный хук ${hookName}: ${hookTime.toFixed(2)}мс`);
      }

      return result;
    }
    return originalCall.apply(this, arguments);
  };

  // Отслеживаем изменения HP напрямую
  const originalActorUpdate = Actor.prototype.update;
  Actor.prototype.update = function(updateData, options) {
    if (debug.enabled && this.type === 'character') {
      const oldMaxHP = this.system?.attributes?.hp?.max;
      const hpMaxChanging = updateData?.system?.attributes?.hp?.max !== undefined;

      if (hpMaxChanging) {
        console.log(`%c[HP Lag Debug] ⚠️ ИЗМЕНЕНИЕ max HP обнаружено`, 'color: red; font-weight: bold;');
        console.log(`[HP Lag Debug] Актер: ${this.name} (${this.id})`);
        console.log(`[HP Lag Debug] Старое max HP: ${oldMaxHP}`);
        console.log(`[HP Lag Debug] Новое max HP: ${updateData.system.attributes.hp.max}`);
        console.log(`[HP Lag Debug] updateData:`, updateData);
        console.trace('[HP Lag Debug] Stack trace изменения HP:');
      }
    }

    return originalActorUpdate.apply(this, arguments);
  };

} else {
  // Выводим статистику
  const debug = game[DEBUG_KEY];
  debug.enabled = false;

  console.log('%c[HP Lag Debug] ===== СТАТИСТИКА =====', 'color: blue; font-weight: bold; font-size: 14px;');
  console.log(`[HP Lag Debug] Время мониторинга: ${((Date.now() - debug.startTime) / 1000).toFixed(1)} секунд`);
  console.log(`[HP Lag Debug] Всего вызовов updateActor: ${debug.hooks.length}`);

  if (debug.timings.length > 0) {
    const sortedTimings = [...debug.timings].sort((a, b) => b - a);
    const avgTime = debug.timings.reduce((a, b) => a + b, 0) / debug.timings.length;
    const maxTime = Math.max(...debug.timings);
    const minTime = Math.min(...debug.timings);

    console.log(`[HP Lag Debug] Время выполнения хуков:`);
    console.log(`  - Среднее: ${avgTime.toFixed(3)}мс`);
    console.log(`  - Минимальное: ${minTime.toFixed(3)}мс`);
    console.log(`  - Максимальное: ${maxTime.toFixed(3)}мс`);
    console.log(`  - Медиана: ${sortedTimings[Math.floor(sortedTimings.length / 2)].toFixed(3)}мс`);
    console.log(`  - Топ-10 самых медленных:`, sortedTimings.slice(0, 10).map(t => t.toFixed(3) + 'мс').join(', '));
  }

  console.log(`\n[HP Lag Debug] Статистика по модулям:`);
  const sortedStats = Object.entries(debug.callStats)
    .sort((a, b) => b[1].totalTime - a[1].totalTime);

  for (const [module, stats] of sortedStats) {
    const avgTime = stats.totalTime / stats.count;
    console.log(`  ${module}:`);
    console.log(`    - Вызовов: ${stats.count}`);
    console.log(`    - Общее время: ${stats.totalTime.toFixed(2)}мс`);
    console.log(`    - Среднее время: ${avgTime.toFixed(3)}мс`);
    console.log(`    - Максимальное время: ${stats.maxTime.toFixed(3)}мс`);
  }

  console.log(`\n[HP Lag Debug] Детали вызовов с изменением HP:`);
  const hpChanges = debug.hooks.filter(h => h.hpChanged || h.hpMaxChanged);
  console.log(`Найдено ${hpChanges.length} вызовов с изменением HP:`);

  hpChanges.forEach((call, index) => {
    console.log(`\nВызов #${index + 1}:`);
    console.log(`  - Время: +${call.timestamp}мс от начала`);
    console.log(`  - Актер: ${call.actorName} (${call.actorId})`);
    console.log(`  - Время выполнения: ${call.executionTime.toFixed(3)}мс`);
    console.log(`  - Ключи в updateData: ${call.updateDataKeys}`);
    console.log(`  - HP изменилось: ${call.hpChanged}, max HP изменилось: ${call.hpMaxChanged}`);
    console.log(`  - Stack trace:\n${call.stackTrace}`);
  });

  console.log(`\n%c[HP Lag Debug] ===== КОНЕЦ СТАТИСТИКИ =====`, 'color: blue; font-weight: bold; font-size: 14px;');
  console.log('[HP Lag Debug] Скопируйте весь вывод выше и отправьте разработчику');

  // Очищаем данные
  delete game[DEBUG_KEY];
}

/**
 * BU DEMO: Добавить предмет выбранному актёру (через BUDocumentGateway).
 *
 * ВАЖНО: здесь НЕТ сокетов.
 * Если у тебя нет OWNER на актёра, BUDocumentGateway внутри сам отправит запрос активному ГМу.
 */
(async () => {
  const token = canvas?.tokens?.controlled?.[0];
  const actor = token?.actor;
  if (!actor) return ui.notifications?.error?.("Выбери токен (актёра), которому добавить предмет.");

  const GW = globalThis.BUDocumentGateway;
  if (!GW) return ui.notifications?.error?.("BUDocumentGateway не найден. Убедись что 'Блок управления' активен и мир прогрузился.");

  const itemData = {
    name: `BU Demo Loot (${game.user?.name ?? "user"})`,
    type: "loot",
    img: "icons/svg/item-bag.svg",
    system: {
      quantity: 1,
      weight: 0
    }
  };

  try {
    const created = await GW.actorCreateEmbedded(actor, "Item", [itemData]);
    const createdName = created?.[0]?.name ?? itemData.name;
    ui.notifications?.info?.(`Добавлено: ${createdName} -> ${actor.name}`);
  } catch (e) {
    console.error(e);
    ui.notifications?.error?.(e?.message ?? String(e));
  }
})();

// Реверсивный макрос для замены цветов и радиусов источников света в радиусе от ВЫБРАННОГО ТОКЕНА
// ЛОГИКА РЕВЕРСА:
// 1. Если цвет #b30013 → меняет на none + устанавливает радиусы 40/80 + убирает анимацию
// 2. Если радиусы 40 тусклый + 80 яркий → меняет на 10/15 + цвет #b30013 + анимация "revolving" скорость 5

(async () => {
    const COLOR_A = "#bd0013";
    const COLOR_B = "none";
    const RADIUS_FEET = 10000;
    const ANIMATION_TYPE = "revolving"; // Вращающийся свет
    const ANIMATION_SPEED = 5; // Скорость анимации

    // Параметры для обратного переключения (по радиусам)
    const BRIGHT_MODE_DIM = 40;
    const BRIGHT_MODE_BRIGHT = 80;
    const DIM_MODE_DIM = 10;
    const DIM_MODE_BRIGHT = 15;

    // 1. Получить выбранный токен
    if (canvas.tokens.controlled.length === 0) {
      console.warn("Макрос не выполнен: токен не выбран.");
      return;
    }

    const selectedToken = canvas.tokens.controlled[0]; // Берем первый выделенный токен
    console.log("Макрос активирован от токена:", selectedToken.name || selectedToken.id);

    // 2. Получить центр токена
    const tokenCenter = selectedToken.center; // У PlaceableObject Token есть свойство center {x, y}

    const lights = canvas.lighting.placeables;
    if (!lights || lights.length === 0) {
      // ui.notifications.info("На сцене нет источников света.");
      console.log("На сцене нет источников света.");
      return;
    }

    console.log(`Центр токена (${selectedToken.name || selectedToken.id}): X=${tokenCenter.x}, Y=${tokenCenter.y}`);
    console.log(`Радиус поиска: ${RADIUS_FEET} футов.`);

    const lightUpdates = [];

    for (const light of lights) {
      const lightCenter = light.center;
      const pathToLight = [tokenCenter, lightCenter];
      const distanceToLight = canvas.grid.measurePath(pathToLight).distance;

      if (distanceToLight <= RADIUS_FEET) {
        console.log(`Источник ${light.id} в радиусе ${RADIUS_FEET} футов от токена (Расстояние: ${distanceToLight} футов).`);

        const currentColorObject = light.document.config.color;
        const currentDim = light.document.config.dim || 0;
        const currentBright = light.document.config.bright || 0;
        const currentAnimation = light.document.config.animation?.type;
        const currentSpeed = light.document.config.animation?.speed || 5;

        console.log(`  Текущие параметры: цвет="${currentColorObject}", тусклый=${currentDim}, яркий=${currentBright}, анимация="${currentAnimation || 'нет'}", скорость=${currentSpeed}`);

        let updateData = null;

        // ПРОВЕРКА 1: Переключение по цвету (#b30013 → none + радиусы 40/80 + убрать анимацию)
        if (currentColorObject != null) {
          const colorStringValue = String(currentColorObject).trim().toLowerCase();

          if (colorStringValue === COLOR_A.toLowerCase()) {
            updateData = {
              _id: light.id,
              "config.color": COLOR_B,
              "config.dim": BRIGHT_MODE_DIM,
              "config.bright": BRIGHT_MODE_BRIGHT,
              "config.animation.type": null, // Убираем анимацию
            };
            console.log(`  → Переключение по ЦВЕТУ: ${COLOR_A} → ${COLOR_B} + радиусы ${BRIGHT_MODE_DIM}/${BRIGHT_MODE_BRIGHT} + убрать анимацию`);
          }
        }

        // ПРОВЕРКА 2: Переключение по радиусам (40/80 → 10/15 + цвет + анимация)
        if (!updateData && currentDim === BRIGHT_MODE_DIM && currentBright === BRIGHT_MODE_BRIGHT) {
          updateData = {
            _id: light.id,
            "config.dim": DIM_MODE_DIM,
            "config.bright": DIM_MODE_BRIGHT,
            "config.color": COLOR_A,
            "config.animation.type": ANIMATION_TYPE, // Добавляем анимацию "Вращающийся свет"
            "config.animation.speed": ANIMATION_SPEED, // Устанавливаем скорость 5
          };
          console.log(`  → Переключение по РАДИУСАМ: ${BRIGHT_MODE_DIM}/${BRIGHT_MODE_BRIGHT} → ${DIM_MODE_DIM}/${DIM_MODE_BRIGHT} + цвет ${COLOR_A} + анимация "${ANIMATION_TYPE}" скорость ${ANIMATION_SPEED}`);
}

        // Если есть что обновлять - добавляем в список
        if (updateData) {
          lightUpdates.push(updateData);
        } else {
          console.log(`  → Не подходит ни под одно условие реверса - пропускаем`);
        }
      }
    }

    if (lightUpdates.length > 0) {
      await canvas.scene.updateEmbeddedDocuments("AmbientLight", lightUpdates);
      console.log(`Изменено ${lightUpdates.length} источников света в радиусе ${RADIUS_FEET} футов от токена '${selectedToken.name || selectedToken.id}'.`);

    } else {
      console.log(`В радиусе ${RADIUS_FEET} футов от токена '${selectedToken.name || selectedToken.id}' не найдено источников света для реверса.`);
    }
})();

